def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend each diagonal line of repeated colors in both directions up to
    # the boundaries, stopping at non-background cells.
    colors = sorted({v for row in grid for v in row if v not in (0, 9)})
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) < 2:
            continue
        pairs = [(a, b) for a in cells for b in cells if a < b and abs(a[0]-b[0]) == abs(a[1]-b[1])]
        if not pairs:
            continue
        (r1,c1),(r2,c2) = max(pairs, key=lambda p: abs(p[0][0]-p[1][0]))
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        for sr,sc,step in [(r1,c1,-1),(r2,c2,1)]:
            r,c=sr,sc
            while 0<=r+step*dr<h and 0<=c+step*dc<w:
                r+=step*dr; c+=step*dc
                if out[r][c] == 9:
                    out[r][c] = color
                else:
                    break
    return out
